using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace Frociart {
 internal sealed class CycleOverviewDialog:Form {
  internal readonly FlowCycleView Model;internal readonly FlowCanvas Preview=new FlowCanvas{Dock=DockStyle.Fill,ViewOnly=true};
  internal readonly ComboBox Choice=new FlowComboBox();internal readonly Button Toggle,Open,Parameters;
  private readonly Panel host=new Panel{Dock=DockStyle.Fill};private readonly Label status=Ui.Label("",10,Ui.Muted);private FlowCycleView.Projection projection;
  internal string NavigateId,EditCheck;private bool loading;
  private FlowCycle.Info Selected {get{return Choice.SelectedIndex<0?null:Model.Cycles[Choice.SelectedIndex];}}
  internal CycleOverviewDialog(Diagram graph){Model=new FlowCycleView(graph);Text="Panoramica cicli — Frociart";StartPosition=FormStartPosition.CenterParent;ShowInTaskbar=false;Font=Ui.Font();AutoScaleMode=AutoScaleMode.Dpi;AutoScaleDimensions=new SizeF(96,96);ClientSize=new Size(900,740);MinimumSize=new Size(620,560);KeyPreview=true;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=4};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,56));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,100));Controls.Add(layout);
   var help=Ui.Label("Panoramica dei cicli\nTocca un ciclo per espanderlo. Apri il foglio per modificare o eseguire.",11,Ui.Ink,true);help.Dock=DockStyle.Fill;layout.Controls.Add(help,0,0);
   var tools=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};tools.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));tools.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,162));Choice.Dock=DockStyle.Fill;Choice.DropDownStyle=ComboBoxStyle.DropDownList;Choice.AccessibleName="Ciclo della panoramica";foreach(var c in Model.Cycles)Choice.Items.Add(c.Header.Length>110?c.Header.Substring(0,107)+"…":c.Header);tools.Controls.Add(Choice,0,0);Toggle=Ui.Button("Espandi ciclo",154,()=>{if(Selected==null)return;Model.Set(Selected.Check,!Model.IsFolded(Selected.Check));RefreshGraph();});Toggle.Dock=DockStyle.Fill;tools.Controls.Add(Toggle,1,0);layout.Controls.Add(tools,0,1);
   host.Controls.Add(Preview);layout.Controls.Add(host,0,2);Preview.ReadOnlyNodeTapped+=Tap;
   var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));footer.RowStyles.Add(new RowStyle(SizeType.Absolute,45));footer.RowStyles.Add(new RowStyle(SizeType.Percent,100));status.Dock=DockStyle.Fill;footer.Controls.Add(status,0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};actions.Controls.Add(Ui.Button("Tutto",72,()=>Preview.ArrangeAnimated(()=>{})));actions.Controls.Add(Ui.Button("Espandi tutti",120,()=>{Model.All(false);RefreshGraph();}));actions.Controls.Add(Ui.Button("Riduci tutti",112,()=>{Model.All(true);RefreshGraph();}));Parameters=Ui.Button("Parametri…",112,()=>{if(Selected==null)return;EditCheck=Selected.Check;DialogResult=DialogResult.Yes;Close();});actions.Controls.Add(Parameters);Open=Ui.Button("Apri sul foglio",145,()=>{if(NavigateId==null)return;DialogResult=DialogResult.OK;Close();},true);actions.Controls.Add(Open);var close=Ui.Button("Chiudi",90,Close);actions.Controls.Add(close);CancelButton=close;footer.Controls.Add(actions,0,1);layout.Controls.Add(footer,0,3);
   Action resizeFooter=()=>{int available=Math.Max(1,layout.ClientSize.Width-layout.Padding.Horizontal-12),line=0,rows=1,height=0;foreach(Control c in actions.Controls){int width=c.Width+c.Margin.Horizontal;if(line>0&&line+width>available){rows++;line=0;}line+=width;height=Math.Max(height,c.Height+c.Margin.Vertical);}layout.RowStyles[3].Height=footer.RowStyles[0].Height+rows*height+12;};ClientSizeChanged+=delegate{resizeFooter();};Shown+=delegate{resizeFooter();};
   Choice.SelectedIndexChanged+=delegate{if(loading)return;if(Selected!=null){NavigateId=Selected.Entry;State();}};loading=true;if(Choice.Items.Count>0)Choice.SelectedIndex=0;loading=false;NavigateId=Selected==null?null:Selected.Entry;RefreshGraph(false);Shown+=delegate{Preview.FitToView();};Ui.ApplyTheme(this);FlowFormMotion.Attach(this);
  }
  private void Tap(string id){FlowCycle.Info card;if(projection.Cards.TryGetValue(id,out card)){Choice.SelectedIndex=Model.Cycles.IndexOf(card);Model.Set(card.Check,false);NavigateId=card.Entry;RefreshGraph();return;}NavigateId=id;var c=Model.Cycles.Where(i=>i.Members.Contains(id)).OrderBy(i=>i.Members.Count).FirstOrDefault();loading=true;Choice.SelectedIndex=c==null?-1:Model.Cycles.IndexOf(c);loading=false;Preview.SelectNode(id);State();}
  private void State(){Toggle.Enabled=Parameters.Enabled=Selected!=null;Toggle.Text=Selected!=null&&Model.IsFolded(Selected.Check)?"Espandi ciclo":"Riduci ciclo";Open.Enabled=NavigateId!=null;status.Text=Selected==null?(Model.Cycles.Count==0?"Nessun ciclo con ingresso e uscita univoci. Il diagramma resta visibile.":"Scegli un ciclo o un blocco da aprire sul foglio."):Selected.Header+" · "+Selected.Members.Count+" blocchi";status.AccessibleName=status.Text;}
  internal void RefreshGraph(bool animate=true){if(animate)FlowTransitions.Change(host);var previous=projection;projection=Model.Build();Preview.ReplaceNavigationGraph(projection,previous,animate);State();}
  protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==Keys.Escape){Close();return true;}return base.ProcessCmdKey(ref msg,keyData);}
 }
 internal sealed partial class MainForm {
  private void ShowCycleOverview(){if(Canvas.IsPointerGestureActive)return;CommitInspector();PauseRun();using(var dialog=new CycleOverviewDialog(Document)){var outcome=dialog.ShowDialog(this);if(outcome==DialogResult.OK&&dialog.NavigateId!=null){Canvas.SelectNode(dialog.NavigateId);Canvas.CenterOnNode(dialog.NavigateId);SetStatus("Blocco aperto sul foglio · doppio clic per modificarlo.");}else if(outcome==DialogResult.Yes){var info=FlowCycle.Find(Document).FirstOrDefault(c=>c.Check==dialog.EditCheck);if(info!=null)EditCycleParameters(info);}}}
 }
 public partial class FlowCanvas {
  private IDictionary<string,string> navigationCaptions;
  internal string NavigationCaption(string id,string fallback){if(IsFoldCard(id))return FlowCycleView.Caption(foldProjection.Cards[id]);string value;return navigationCaptions!=null&&navigationCaptions.TryGetValue(id,out value)?value:fallback;}
  internal void ReplaceNavigationGraph(FlowCycleView.Projection next,FlowCycleView.Projection previous,bool animate){EnsureScene();var before=_nodeVisuals.ToDictionary(n=>n.Id,n=>new PointF(n.Bounds.X,n.Bounds.Y));var sizes=_nodeVisuals.ToDictionary(n=>n.Id,n=>n.Bounds.Size);float x=_panX,y=_panY,z=_zoom;Diagram=next.Graph;navigationCaptions=next.Cards.ToDictionary(c=>c.Key,c=>FlowCycleView.Caption(c.Value));EnsureScene();FitToView();if(!animate||!UiMotion.Enabled)return;
   foreach(var n in next.Graph.Nodes)if(!before.ContainsKey(n.Id)){string owner;PointF origin;if(previous!=null&&previous.Owner.TryGetValue(n.Id,out owner)&&before.TryGetValue(owner,out origin))before[n.Id]=origin;}
   foreach(var n in next.Graph.Nodes){SizeF size;if(sizes.TryGetValue(n.Id,out size)&&size!=FlowSizing.Size(n))sizeMotion[n.Id]=new SizeMotion{From=size,To=FlowSizing.Size(n),At=manipulationClock.ElapsedMilliseconds};}
   arrangeFromX=x;arrangeFromY=y;arrangeFromZoom=z;arrangeToX=_panX;arrangeToY=_panY;arrangeToZoom=_zoom;_panX=x;_panY=y;_zoom=z;arrangeCamera=true;AnimatePlacement(before);RaiseViewChanged();RequestFrameRepaint();
  }
 }
}
